import { CapsuleFormat, GrammarCapsule, GrammarExample, GrammarInteraction, GrammarLevel, GrammarSkill, LearningFunction } from "@/lib/grammar/types";

const AZAR = "(Betty Azar).Understanding and Using English Grammar blue.pdf";
const PROMPTS = "PROMPT MAESTRO LANCELOT ACTIVIDADES Vs1.txt";

type SkillInput = Omit<GrammarSkill, "sourceReferences" | "placementConfidence"> & { chapter: string; page: number; examples: [GrammarExample, GrammarExample, GrammarExample] };

function item(prompt: string, answer: string, choices: string[], wrong: string, sentence: string, feedback: string): GrammarExample {
  return { prompt, answer, choices, wrong, sentence, feedback };
}

function skill(input: SkillInput): GrammarSkill {
  return { ...input, sourceReferences: [{ fileName: AZAR, page: input.page, section: input.chapter }, { fileName: PROMPTS, section: "Active Learning, error as data and Eureka" }], placementConfidence: "strong-inference" };
}

